<?php
require_once __DIR__ . '/public/db_connect.php';

try {  echo "Starting self-heal to drop generated column and add VARCHAR customer_id...\n";  // Check if customer_id exists and is generated  $stmt = $pdo->query("SHOW CREATE TABLE customers");  $createTable = $stmt->fetch(PDO::FETCH_ASSOC)['Create Table'];  if (strpos($createTable, '`customer_id` int(11) GENERATED') !== false || strpos($createTable, 'GENERATED ALWAYS AS') !== false) {  echo "Dropping generated customer_id column...\n";  $pdo->exec("ALTER TABLE customers DROP COLUMN customer_id");  }  // Check if customer_id exists now (in case it was already dropped or is normal)  $check_cols = $pdo->query("SHOW COLUMNS FROM customers");  $cols = $check_cols->fetchAll(PDO::FETCH_COLUMN);  if (!in_array('customer_id', $cols)) {  echo "Adding customer_id as VARCHAR(50)...\n";  $pdo->exec("ALTER TABLE customers ADD COLUMN customer_id VARCHAR(50) DEFAULT NULL");  $pdo->exec("ALTER TABLE customers ADD INDEX idx_customer_id_val (customer_id)");  }  // Populate customer_id for all rows  echo "Populating customer_ids...\n";  $customers = $pdo->query("SELECT * FROM customers")->fetchAll(PDO::FETCH_ASSOC);  $updateStmt = $pdo->prepare("UPDATE customers SET customer_id = ? WHERE id = ?");  foreach ($customers as $c) {  $stationId = $c['station_id'] ?: 1253;  $regDate = $c['registered_at'] ?: $c['created_at'] ?: date('Y-m-d H:i:s');  $yearMonth = date('Ym', strtotime($regDate));  $seq = str_pad($c['id'], 3, '0', STR_PAD_LEFT);  $cust_id = "CUS-{$stationId}-{$yearMonth}-{$seq}";  $updateStmt->execute([$cust_id, $c['id']]);  }  echo "SUCCESS: customer_id successfully converted to VARCHAR(50) and populated!\n";  } catch (Exception $e) {  echo "ERROR: " . $e->getMessage() . "\n";
}
?>
